        sm.reload(pal.paint(hex("#aab0b7"), 0.1), 0.6);
        c.drag(&mut sm, &Gesture::new(vec![(x0 - 4.0, y0 + 4.0), (x0 + 40.0, y0 + 7.5), (x0 + 88.0, y0 + 10.0)]).pressure(0.5, 0.2).ramps(0.2, 0.4).shake(0.3), None);
    }
